// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title SearchIndexer
 * @notice Maintains a search index with circuit breaker protection
 * @dev Uses batch processing with configurable thresholds
 */
contract SearchIndexer {
    struct IndexEntry {
        bytes32 contentHash;
        uint256 timestamp;
        uint256 relevanceScore;
        address submitter;
    }

    struct CircuitBreaker {
        uint256 failureCount;
        uint256 lastFailureTime;
        uint256 cooldownPeriod;
        uint256 failureThreshold;
        bool isOpen;
    }

    struct BatchContext {
        uint256 startOffset;
        uint256 processedCount;
        uint256 totalRequested;
        uint256 windowSize;
    }

    mapping(uint256 => IndexEntry) public entries;
    uint256 public totalEntries;
    uint256 public constant MAX_BATCH_SIZE = 50;
    uint256 public constant MIN_WINDOW_SIZE = 5;

    CircuitBreaker public breaker;
    address public owner;

    event IndexUpdated(uint256 indexed entryId, bytes32 contentHash);
    event CircuitBreakerTripped(uint256 failureCount);
    event BatchProcessed(uint256 startOffset, uint256 count);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier circuitClosed() {
        _checkCircuitBreaker();
        _;
    }

    constructor(uint256 _cooldownPeriod, uint256 _failureThreshold) {
        owner = msg.sender;
        breaker = CircuitBreaker({
            failureCount: 0,
            lastFailureTime: 0,
            cooldownPeriod: _cooldownPeriod,
            failureThreshold: _failureThreshold,
            isOpen: false
        });
    }

    function addEntry(bytes32 _contentHash, uint256 _relevanceScore) external circuitClosed {
        require(_contentHash != bytes32(0), "Empty hash");
        require(_relevanceScore > 0 && _relevanceScore <= 1000, "Invalid score");

        entries[totalEntries] = IndexEntry({
            contentHash: _contentHash,
            timestamp: block.timestamp,
            relevanceScore: _relevanceScore,
            submitter: msg.sender
        });

        emit IndexUpdated(totalEntries, _contentHash);
        totalEntries++;
    }

    /**
     * @notice Compute the effective search window boundaries
     * @dev Calculates pagination offset using batch context
     * @param ctx The batch processing context
     * @return adjustedStart The adjusted start position
     * @return adjustedEnd The adjusted end position  
     */
    function _computeSearchWindow(BatchContext memory ctx) 
        internal 
        pure 
        returns (uint256 adjustedStart, uint256 adjustedEnd) 
    {
        // Calculate remaining items to process
        uint256 remaining = ctx.totalRequested - ctx.processedCount;

        // Determine effective window: use smaller of remaining and windowSize
        uint256 effectiveWindow = remaining < ctx.windowSize ? remaining : ctx.windowSize;

        // Apply offset normalization: startOffset is the base,
        // processedCount tracks progress through the batch
        // The adjustment accounts for already-processed entries
        adjustedStart = ctx.startOffset + ctx.processedCount;

        // Critical: compute end boundary
        // When processedCount exceeds startOffset due to wraparound batching,
        // we need to handle the underflow case for reverse indexing
        adjustedEnd = adjustedStart + effectiveWindow;

        return (adjustedStart, adjustedEnd);
    }

    /**
     * @notice Query a range of entries with relevance filtering
     * @param startFrom Starting index for the search
     * @param count Number of entries to retrieve
     * @param minRelevance Minimum relevance score filter
     */
    function queryEntries(
        uint256 startFrom,
        uint256 count,
        uint256 minRelevance
    ) external view circuitClosed returns (bytes32[] memory results) {
        require(count <= MAX_BATCH_SIZE, "Batch too large");
        require(startFrom < totalEntries || totalEntries == 0, "Start out of bounds");

        if (totalEntries == 0) return new bytes32[](0);

        BatchContext memory ctx = BatchContext({
            startOffset: startFrom,
            processedCount: 0,
            totalRequested: count,
            windowSize: count < MIN_WINDOW_SIZE ? MIN_WINDOW_SIZE : count
        });

        results = new bytes32[](count);
        uint256 found = 0;

        while (ctx.processedCount < ctx.totalRequested) {
            (uint256 wStart, uint256 wEnd) = _computeSearchWindow(ctx);

            if (wStart >= totalEntries) break;
            if (wEnd > totalEntries) wEnd = totalEntries;

            for (uint256 i = wStart; i < wEnd && found < count; i++) {
                if (entries[i].relevanceScore >= minRelevance) {
                    results[found] = entries[i].contentHash;
                    found++;
                }
            }
            ctx.processedCount += (wEnd - wStart);
        }

        return results;
    }

    /**
     * @notice Batch reindex entries with offset recalculation
     * @dev Handles sparse index compaction
     * @param fromIndex Start of reindex range
     * @param batchSize Number of entries to reindex
     * @param scoreAdjustment Adjustment to apply to relevance scores
     */
    function reindexBatch(
        uint256 fromIndex,
        uint256 batchSize,
        int256 scoreAdjustment
    ) external onlyOwner circuitClosed {
        require(batchSize <= MAX_BATCH_SIZE, "Batch too large");
        require(fromIndex < totalEntries, "Invalid start");

        uint256 effectiveEnd = fromIndex + batchSize;
        if (effectiveEnd > totalEntries) effectiveEnd = totalEntries;

        for (uint256 i = fromIndex; i < effectiveEnd; i++) {
            IndexEntry storage entry = entries[i];
            if (entry.contentHash == bytes32(0)) continue;

            // Apply score adjustment with bounds
            uint256 currentScore = entry.relevanceScore;
            uint256 newScore;

            if (scoreAdjustment >= 0) {
                newScore = currentScore + uint256(scoreAdjustment);
                if (newScore > 1000) newScore = 1000;
            } else {
                uint256 absAdjustment = uint256(-scoreAdjustment);
                if (absAdjustment >= currentScore) {
                    newScore = 1;
                } else {
                    newScore = currentScore - absAdjustment;
                }
            }

            // Ensure minimum score of 1 for active entries
            if (newScore == 0 || newScore > 1000) newScore = 1;

            entry.relevanceScore = newScore;
            entry.timestamp = block.timestamp;
        }

        emit BatchProcessed(fromIndex, effectiveEnd - fromIndex);
    }

    /**
     * @notice Remove entries and compact the index
     * @param indices Array of entry indices to remove
     */
    function removeEntries(uint256[] calldata indices) external onlyOwner circuitClosed {
        for (uint256 i = 0; i < indices.length; i++) {
            require(indices[i] < totalEntries, "Invalid index");
            delete entries[indices[i]];
        }
        // Note: totalEntries not decremented to maintain index stability
    }

    /**
     * @notice Calculate pagination metadata for search results
     * @param pageSize Items per page
     * @param currentPage Current page number (0-indexed)
     * @return offset The starting offset
     * @return limit The number of items to fetch
     * @return totalPages Total number of pages
     */
    function getPaginationMeta(uint256 pageSize, uint256 currentPage)
        external
        view
        returns (uint256 offset, uint256 limit, uint256 totalPages)
    {
        require(pageSize > 0 && pageSize <= MAX_BATCH_SIZE, "Invalid page size");

        totalPages = (totalEntries + pageSize - 1) / pageSize;

        // Calculate offset with bounds checking
        offset = currentPage * pageSize;

        // Safe bounds check: ensure offset doesn't exceed totalEntries
        if (offset >= totalEntries) {
            limit = 0;
        } else {
            limit = totalEntries - offset;
            if (limit > pageSize) limit = pageSize;
        }

        return (offset, limit, totalPages);
    }

    function _checkCircuitBreaker() internal view {
        if (breaker.isOpen) {
            require(
                block.timestamp >= breaker.lastFailureTime + breaker.cooldownPeriod,
                "Circuit breaker is open"
            );
        }
    }

    function reportFailure() external onlyOwner {
        breaker.failureCount++;
        breaker.lastFailureTime = block.timestamp;

        if (breaker.failureCount >= breaker.failureThreshold) {
            breaker.isOpen = true;
            emit CircuitBreakerTripped(breaker.failureCount);
        }
    }

    function resetCircuitBreaker() external onlyOwner {
        breaker.failureCount = 0;
        breaker.isOpen = false;
    }
}
